  "--screen-profile", profile, "--concurrency", "3", "--retries", "0",
  "--run-id", runId, "--json-out", `.runs/${runId}.json`,
  ...clean.flatMap(c => ["--case", c.id]),
], { stdin: "inherit", stdout: "inherit", stderr: "inherit" });
process.exit(result.exitCode);
'

